// Parses one comma-separated component-code field of a MonSeq/monster txt row into the row's compiled code table. For sequence slot nSeqSlot (<0x10) it clears the slot's count byte and three code entries, strips surrounding quotes, then tokenizes the input string on commas; each <=4-char token is packed into a 4-char code (space-padded), resolved to a class id via Excel GetClassIdFromName against pTxtCompCodeLink, and stored as a byte. Writes the resolved code count back to offset 0x15+nSeqSlot (max 12 codes). On the final slot (0xf) it sums frame counts across the parsed component groups and stores the clamped (<=0xfe) total at offset 0x25. Pure table-build side effects; no return.
void __fastcall MONSTERTBLS_ParseMonSeqField(char * szText, char * pRecord, uint32_t nSeqSlot, int32_t nLinkerCtx1, int32_t nLinkerCtx2, int32_t nLinkerCtx3) {
    char* pTokenEnd;
    int32_t nClassId;
    uint32_t dwCodeBuf;
    char cChar2;
    if (!(pRecord && nSeqSlot <= 0xf)) {
      return;
    }

    pRecord[nSeqSlot + 0x15] = '\0';
    char* pcVar1 = pRecord + nSeqSlot * 0xc + 0x26;
    pcVar1[0] = -1;
    pcVar1[1] = -1;
    pcVar1[2] = -1;
    pcVar1[3] = -1;
    pcVar1[4] = -1;
    pcVar1[5] = -1;
    pcVar1[6] = -1;
    pcVar1[7] = -1;
    pcVar1[8] = -1;
    pcVar1[9] = -1;
    pcVar1[10] = -1;
    pcVar1[0xb] = -1;
    if (!szText) {
      return;
    }
    if (*szText == '\"') {
      szText++;
    }

    char cChar = *szText;
    char* pComma = szText;
    while (cChar != '\0') {
      if (*pComma == '\"') {
        *pComma = '\0';
      }

      pComma++;
      cChar = *pComma;
    }

    int nCodeLen = 0;
    while (true) {
      char* pszNextToken;
      pszNextToken = strchr(szText, 0x2c);
      if (pszNextToken) {
        *pszNextToken = '\0';
        pszNextToken++;
      }
      if (!szText) {
        break;
      }

      cChar = *szText;
      if (cChar == '\0') {
        break;
      }

      pTokenEnd = szText;
      pTokenEnd = pTokenEnd + strlen(pTokenEnd) + 1;
      if ((uint32_t)((int)pTokenEnd - (int)(szText + 1)) > 4) {
        break;
      }
      if (szText[1] == '\0') {
        *(uint16_t*)(char*)&dwCodeBuf = (uint16_t)((uint16_t)(uint8_t)0x20 << 8 | (uint16_t)(uint8_t)cChar);
        d2_store24((char*)&dwCodeBuf, (uint32_t)((uint32_t)((uint32_t)(uint8_t)0x20 << 16 | (uint32_t)(uint16_t)dwCodeBuf) & 0xffffffu));
        dwCodeBuf = (uint32_t)((uint32_t)(uint8_t)0x20 << 24 | (uint32_t)((uint32_t)dwCodeBuf & 0xffffffu));
      } else {
        *(uint16_t*)(char*)&dwCodeBuf = (uint16_t)((uint16_t)(uint8_t)szText[1] << 8 | (uint16_t)(uint8_t)cChar);
        if (szText[2] == '\0') {
          d2_store24((char*)&dwCodeBuf, (uint32_t)((uint32_t)((uint32_t)(uint8_t)0x20 << 16 | (uint32_t)(uint16_t)dwCodeBuf) & 0xffffffu));
          dwCodeBuf = (uint32_t)((uint32_t)(uint8_t)0x20 << 24 | (uint32_t)((uint32_t)dwCodeBuf & 0xffffffu));
        } else {
          d2_store24((char*)&dwCodeBuf, (uint32_t)((uint32_t)((uint32_t)(uint8_t)szText[2] << 16 | (uint32_t)(uint16_t)dwCodeBuf) & 0xffffffu));
          dwCodeBuf = (uint32_t)((uint32_t)(uint8_t)0x20 << 24 | (uint32_t)((uint32_t)dwCodeBuf & 0xffffffu));
          if (szText[3] != '\0') {
            dwCodeBuf = (uint32_t)((uint32_t)(uint8_t)szText[3] << 24 | (uint32_t)((uint32_t)dwCodeBuf & 0xffffffu));
          }
        }
      }

      nClassId = Fog::Src::Excel::GetClassIdFromName(sgtDataTable.pTxtCompCodeLink, dwCodeBuf, 1);
      pcVar1[nCodeLen] = (char)nClassId;
      nCodeLen++;
      if (!pszNextToken) {
        break;
      }

      szText = pszNextToken;
      if (nCodeLen >= 0xc) {
        break;
      }
    }

    pRecord[nSeqSlot + 0x15] = (char)nCodeLen;
    if (nSeqSlot != 0xf) {
      return;
    }

    int nTotalFrames = 0;
    uint8_t* pFrameCount = (uint8_t*)(pRecord + 0x16);
    int nLoopCount = 4;
    do {
      if (pFrameCount[-1] > 1) {
        nTotalFrames = nTotalFrames - 1 + (uint32_t)pFrameCount[-1];
      }
      if (*pFrameCount > 1) {
        nTotalFrames = nTotalFrames - 1 + (uint32_t)*pFrameCount;
      }
      if (pFrameCount[1] > 1) {
        nTotalFrames = nTotalFrames - 1 + (uint32_t)pFrameCount[1];
      }
      if (pFrameCount[2] > 1) {
        nTotalFrames = nTotalFrames - 1 + (uint32_t)pFrameCount[2];
      }

      pFrameCount += 4;
      nLoopCount--;
    } while (nLoopCount);

    if (nTotalFrames > 0xfe) {
      nTotalFrames = 0xfe;
    }

    pRecord[0x25] = (char)nTotalFrames;
}

